# synth_kit.py [film folder]: the 12 one-shot sounds the film's mixer expects (audio/sfx/<name>.wav), synthesized in code
# instead of generated by a paid model. Deterministic (fixed seed), 48 kHz stereo, 16-bit.
import numpy as np, wave, os, sys
SR = 48000
rng = np.random.default_rng(7)
out = os.path.join(sys.argv[1] if len(sys.argv) > 1 else '.', 'audio', 'sfx'); os.makedirs(out, exist_ok=True)
t_ = lambda d: np.arange(int(d * SR)) / SR
def lp(x, fc):            # one-pole low-pass (fc may be an array: a sweeping cutoff)
    fc = np.broadcast_to(fc, x.shape); a = np.exp(-2 * np.pi * fc / SR); y = np.empty_like(x); s = 0.0
    for i in range(len(x)): s = (1 - a[i]) * x[i] + a[i] * s; y[i] = s
    return y
hp = lambda x, fc: x - lp(x, fc)
def bp(x, lo, hi): return hp(lp(x, hi), lo)
def env(d, a, r, curve=4):  # attack then exponential release
    t = t_(d); e = np.minimum(1, t / max(a, 1e-4)); return e * np.exp(-curve * np.maximum(0, t - a) / max(r, 1e-4))
def save(name, x, width=0.25):
    x = x / (np.abs(x).max() + 1e-9) * 0.89
    d = np.roll(x, int(.004 * SR)) * width            # a little stereo width from a short delay
    st = np.stack([x + d * .5, x - d * .5], 1); st /= np.abs(st).max() / .89
    with wave.open(os.path.join(out, name + '.wav'), 'wb') as w:
        w.setnchannels(2); w.setsampwidth(2); w.setframerate(SR); w.writeframes((st * 32767).astype('<i2').tobytes())
noise = lambda d: rng.standard_normal(int(d * SR))
def sweep(f0, f1, d, shape='sin'):
    t = t_(d); f = f0 * (f1 / f0) ** (t / d); ph = 2 * np.pi * np.cumsum(f) / SR
    return np.sin(ph) if shape == 'sin' else 2 * ((ph / (2 * np.pi)) % 1) - 1

# whooshes: band-limited noise whose cutoff rises and falls with the swell, peak at 60 %
def whoosh(d, lo, hi, sub=0):
    t = t_(d); sw = np.sin(np.pi * np.clip(t / d, 0, 1)) ** 2
    x = lp(noise(d), lo + (hi - lo) * sw) * sw
    if sub: x += sub * sweep(70, 40, d) * sw
    return x
save('whoosh_1', whoosh(.7, 300, 5000)); save('whoosh_2', whoosh(.7, 250, 6500)); save('whoosh_big', whoosh(1.3, 120, 3000, sub=.6))
# impacts: a pitched-down sine body with a filtered noise transient
def impact(d, body=1.0, metal=0.0):
    x = body * sweep(110, 38, d) * env(d, .003, d * .5) + .7 * lp(noise(d), 2500) * env(d, .001, .12, 6)
    if metal:
        for f in (523, 811, 1187, 1663): x += metal * .25 * np.sin(2 * np.pi * f * t_(d)) * env(d, .002, d * .35, 5)
    return x
save('impact', impact(1.2)); save('impact_big', impact(2.2, 1.2, .8))
save('hit', hp(noise(.5), 1200) * env(.5, .001, .06, 7) + .6 * sweep(220, 90, .5) * env(.5, .001, .08))
save('slash', hp(noise(.6), 2500) * np.sin(np.pi * np.clip(t_(.6) / .35, 0, 1)) ** 3)
for k, f in ((1, 2400), (2, 2000)):
    save(f'key_{k}', hp(noise(.3), 1500) * env(.3, .0005, .012, 8) + .5 * np.sin(2 * np.pi * f * t_(.3)) * env(.3, .0005, .02, 8), .1)
save('pop', sweep(380, 950, .3) * env(.3, .002, .06, 5), .1)
save('tick', np.sin(2 * np.pi * 3200 * t_(.25)) * env(.25, .0005, .015, 8), .05)
r = t_(2.2) / 2.2
save('riser', (lp(noise(2.2), 200 + 7000 * r ** 2) * .8 + .35 * sweep(110, 880, 2.2, 'saw')) * r ** 2.2)
g = np.zeros(int(.6 * SR))
for i in range(9):                                     # a stutter of short square bursts
    a = int(i * .06 * SR); n = int(rng.uniform(.015, .045) * SR); f = rng.uniform(300, 2400)
    g[a:a + n] += np.sign(np.sin(2 * np.pi * f * np.arange(n) / SR)) * .6
save('glitch', g, .4)
d = 3.0; lh = sweep(90, 32, d) * env(d, .004, 2.2, 3)
for f in (880, 1320, 1975, 2637): lh += .12 * np.sin(2 * np.pi * f * t_(d) + f) * env(d, .01, 2.6, 2.5)
save('logo_hit', lh + .5 * lp(noise(d), 1800) * env(d, .001, .2, 6))
print('kit:', sorted(os.listdir(out)))
